CREATE POLICY "Users read own business logo" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'business-logos' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Users upload own business logo" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'business-logos' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Users update own business logo" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'business-logos' AND (storage.foldername(name))[1] = auth.uid()::text) WITH CHECK (bucket_id = 'business-logos' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Users delete own business logo" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'business-logos' AND (storage.foldername(name))[1] = auth.uid()::text);